import math
import re
import xml.etree.ElementTree as ET


import logging


logger = logging.getLogger("desktopenv.metrics.inkscape")


def _parse_style(style_str):
    """Parse CSS-like style string 'fill:#ff0000;stroke:#000' into dict."""
    if not style_str:
        return {}
    result = {}
    for part in style_str.split(';'):
        part = part.strip()
        if ':' in part:
            key, val = part.split(':', 1)
            result[key.strip()] = val.strip()
    return result


def _normalize_color(color):
    """Normalize hex colors: #f00 → #ff0000, uppercase → lowercase. 'none' stays 'none'."""
    if not color:
        return None
    color = color.strip().lower()
    if color == 'none':
        return 'none'
    if color.startswith('#'):
        hex_part = color[1:]
        if len(hex_part) == 3:
            hex_part = ''.join(c * 2 for c in hex_part)
        elif len(hex_part) == 8:
            # #rrggbbaa → just take rrggbb
            hex_part = hex_part[:6]
        return '#' + hex_part.lower()
    # Named colors — just return as-is for now
    return color


def _find_element_by_id(root, element_id):
    """Find element by id attribute across all elements."""
    for elem in root.iter():
        if elem.get('id') == element_id:
            return elem
    return None


def _get_style_prop(elem, prop):
    """Get a style property from either inline style or direct attribute."""
    style = _parse_style(elem.get('style', ''))
    if prop in style:
        return style[prop]
    return elem.get(prop)


def _get_float(value, default=None):
    """Safely convert a CSS/SVG numeric value to float."""
    if value is None:
        return default
    try:
        return float(re.sub(r'[a-zA-Z%]+$', '', str(value).strip()))
    except (ValueError, TypeError):
        return default


def _parse_svg(svg_file_path):
    """Parse SVG file and return (tree, root). Returns (None, None) on error."""
    try:
        tree = ET.parse(svg_file_path)
        return tree, tree.getroot()
    except Exception:
        return None, None


def _tag_local(elem):
    """Get local tag name without namespace."""
    tag = elem.tag
    if '}' in tag:
        return tag.split('}', 1)[1]
    return tag


def _get_transform_value(elem):
    transform = elem.get('transform', '') or ''
    style_transform = _get_style_prop(elem, 'transform') or ''
    return f"{transform} {style_transform}".strip()


def _parse_transform_numbers(raw):
    return [_get_float(part) for part in re.split(r'[\s,]+', raw.strip()) if part.strip()]


def _extract_transform_commands(transform):
    commands = []
    for match in re.finditer(r'([a-zA-Z]+)\s*\(([^)]*)\)', transform or ''):
        commands.append((match.group(1).lower(), _parse_transform_numbers(match.group(2))))
    return commands


def _angle_delta(actual, expected):
    return abs((actual - expected + 180.0) % 360.0 - 180.0)


def _matrix_rotation_and_scale(values):
    if len(values) < 6:
        return None, None
    a, b, c, d = values[:4]
    sx = math.hypot(a, b)
    sy = math.hypot(c, d)
    angle = math.degrees(math.atan2(b, a)) if sx else None
    return angle, (sx, sy)


def check_inkscape_fill_color(svg_file_path, rule):
    """Verify element fill color.
    rule: {"element_id": str, "expected_fill": str}
    """
    _, root = _parse_svg(svg_file_path)
    if root is None:
        return 0.0

    element_id = rule.get("element_id")
    expected_fill = _normalize_color(rule.get("expected_fill"))

    elem = _find_element_by_id(root, element_id)
    if elem is None:
        return 0.0

    actual_fill = _get_style_prop(elem, 'fill')
    # For text elements, also check tspan children for fill
    if actual_fill is None and _tag_local(elem) == 'text':
        for child in elem:
            if _tag_local(child) == 'tspan':
                actual_fill = _get_style_prop(child, 'fill')
                if actual_fill:
                    break
    actual_fill = _normalize_color(actual_fill)

    if expected_fill == 'none':
        return 1.0 if actual_fill == 'none' else 0.0

    if actual_fill == expected_fill:
        return 1.0
    return 0.0


def check_inkscape_transform(svg_file_path, rule):
    """Verify element has expected transform type and optional numeric values.
    rule: {"element_id": str, "expected_transform_contains": str,
           "expected_rotation_degrees": float, "expected_scale_factor": float}
    """
    _, root = _parse_svg(svg_file_path)
    if root is None:
        return 0.0

    element_id = rule.get("element_id")
    expected_contains = rule.get("expected_transform_contains", "")
    expected_rotation = _get_float(rule.get("expected_rotation_degrees"))
    expected_scale = _get_float(rule.get("expected_scale_factor"))
    tolerance = _get_float(rule.get("tolerance"), 2.0)

    elem = _find_element_by_id(root, element_id)
    if elem is None:
        return 0.0

    transform = _get_transform_value(elem)
    if expected_contains and expected_contains not in transform:
        return 0.0

    commands = _extract_transform_commands(transform)

    if expected_rotation is not None:
        found_rotation = False
        for name, values in commands:
            angle = None
            if name == 'rotate' and values:
                angle = values[0]
            elif name == 'matrix':
                angle, _ = _matrix_rotation_and_scale(values)
            if angle is not None and _angle_delta(angle, expected_rotation) <= tolerance:
                found_rotation = True
                break
        if not found_rotation:
            return 0.0

    if expected_scale is not None:
        found_scale = False
        for name, values in commands:
            scales = None
            if name == 'scale' and values:
                sx = values[0]
                sy = values[1] if len(values) > 1 else sx
                scales = (sx, sy)
            elif name == 'matrix':
                _, scales = _matrix_rotation_and_scale(values)
            if scales and all(abs(scale - expected_scale) <= tolerance for scale in scales):
                found_scale = True
                break
        if not found_scale:
            return 0.0

    return 1.0


def check_inkscape_l2_multi_transform(svg_file_path, rule):
    """L2 Task 2-6: Apply two transforms + change fill.
    rule: {"transform_check_1": {...}, "transform_check_2": {...}, "fill_check": {...}}
    """
    if check_inkscape_transform(svg_file_path, rule.get("transform_check_1", {})) < 1.0:
        return 0.0
    if check_inkscape_transform(svg_file_path, rule.get("transform_check_2", {})) < 1.0:
        return 0.0
    if check_inkscape_fill_color(svg_file_path, rule.get("fill_check", {})) < 1.0:
        return 0.0
    return 1.0
